def caesar(s: str, k: int) -> str:
    result = []
    k = k % 26  # Normalize k to range [0, 25]
    for char in s:
        if 'a' <= char <= 'z':
            shifted = chr((ord(char) - ord('a') + k) % 26 + ord('a'))
            result.append(shifted)
        elif 'A' <= char <= 'Z':
            shifted = chr((ord(char) - ord('A') + k) % 26 + ord('A'))
            result.append(shifted)
        else:
            result.append(char)
    return ''.join(result)
```

