def to_snake(name: str) -> str:
    if not name:
        return ""

    result = []
    i = 0

    while i < len(name):
        if name[i].isupper():
            # Check if this uppercase letter starts a new word
            # A run of capitals is treated as one word, unless followed by lowercase
            j = i
            while j < len(name) and name[j].isupper():
                j += 1

            # If the run of capitals is followed by a lowercase letter, split at the last capital
            if j < len(name) and name[j].islower():
                # Add the run of capitals as one word, but split at the last capital
                result.append(name[i:j-1].lower())
                i = j - 1
            else:
                # Otherwise, treat the entire run as one word
                result.append(name[i:j].lower())
                i = j
        else:
            result.append(name[i])
            i += 1

    return "_".join(result)
```

