def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty string not allowed")

    seconds = 0
    i = 0
    units = {'h': 3600, 'm': 60, 's': 1}

    while i < len(s):
        if s[i] in units:
            unit = s[i]
            # Extract the number before the unit
            num_start = i - 1
            while num_start >= 0 and s[num_start].isdigit():
                num_start -= 1
            num_start += 1
            try:
                value = int(s[num_start:i])
            except ValueError:
                raise ValueError(f"Invalid number before {unit}")
            seconds += value * units[unit]
            i += 1
        else:
            raise ValueError(f"Invalid character: {s[i]}")

    return seconds
```

