def word_wrap(text: str, width: int) -> list:
    words = text.split()
    lines = []
    current_line = []
    current_length = 0

    for word in words:
        # Check if adding this word exceeds the width
        word_length = len(word)
        space_needed = 1 if current_line else 0
        if current_length + space_needed + word_length > width:
            # If the word itself is too long, put it on its own line
            if word_length > width:
                if current_line:
                    lines.append(' '.join(current_line))
                    current_line = []
                    current_length = 0
                lines.append(word)
            else:
                # Start a new line with this word
                if current_line:
                    lines.append(' '.join(current_line))
                current_line = [word]
                current_length = word_length
        else:
            # Add the word to current line
            if current_line:
                current_length += space_needed + word_length
            else:
                current_length = word_length
            current_line.append(word)

    # Add the last line if it exists
    if current_line:
        lines.append(' '.join(current_line))

    return lines
```

