def invert_index(docs: dict) -> dict:
    inverted = {}
    for doc_id, text in docs.items():
        words = text.lower().split()
        for word in words:
            if word not in inverted:
                inverted[word] = []
            if doc_id not in inverted[word]:
                inverted[word].append(doc_id)
    for word in inverted:
        inverted[word].sort()
    return inverted
